new_closure <- function(parameter, body, environment) structure(list(parameter = parameter, body = body, environment = environment), class = "ml_closure")
new_builtin <- function(behavior) structure(list(behavior = behavior), class = "ml_builtin")
copy_value_environment <- function(environment) list2env(as.list.environment(environment, all.names = TRUE), parent = emptyenv())
runtime_failure <- function(position, message) stop(structure(list(position = position, message = message), class = c("runtime_failure", "error", "condition")))
checked_integer <- function(value, position) {
  if (value < -2147483648 || value > 2147483647) runtime_failure(position, "integer overflow")
  if (value == 0) 0 else value
}
compare_strings <- function(first, second) {
  left <- utf8ToInt(first)
  right <- utf8ToInt(second)
  for (index in seq_len(min(length(left), length(right)))) {
    if (left[[index]] != right[[index]]) return(sign(left[[index]] - right[[index]]))
  }
  sign(length(left) - length(right))
}
compare_values <- function(first, second, position) {
  if (inherits(first, c("ml_closure", "ml_builtin"))) runtime_failure(position, "functional value compared")
  if (is.list(first)) {
    for (index in seq_len(min(length(first), length(second)))) {
      order <- compare_values(first[[index]], second[[index]], position)
      if (order != 0L) return(order)
    }
    return(sign(length(first) - length(second)))
  }
  if (is.character(first)) return(compare_strings(first, second))
  as.integer(first > second) - as.integer(first < second)
}
binary_operation <- function(operator, first, second, position) {
  first <- force(first)
  second <- force(second)
  if (operator == "+") return(checked_integer(first + second, position))
  if (operator == "-") return(checked_integer(first - second, position))
  if (operator == "*") return(checked_integer(first * second, position))
  if (operator %in% c("/", "mod")) {
    if (second == 0) runtime_failure(position, "division by zero")
    quotient <- trunc(first / second)
    return(if (operator == "/") checked_integer(quotient, position) else first - second * quotient)
  }
  if (operator == "^") return(paste0(first, second))
  if (operator == "::") return(c(list(first), second))
  order <- compare_values(first, second, position)
  switch(operator, "=" = order == 0L, "<>" = order != 0L, "<" = order < 0L,
         ">" = order > 0L, "<=" = order <= 0L, ">=" = order >= 0L)
}
match_pattern <- function(pattern, value, bindings) {
  kind <- pattern$kind
  if (kind == "wildcard") return(TRUE)
  if (kind == "name") {
    assign(pattern$value, value, bindings)
    return(TRUE)
  }
  if (kind %in% c("integer", "boolean", "string")) return(pattern$value == value)
  if (kind == "cons") return(length(value) > 0L && match_pattern(pattern$children[[1L]], value[[1L]], bindings) && match_pattern(pattern$children[[2L]], value[-1L], bindings))
  if (kind == "list" && length(value) != length(pattern$children)) return(FALSE)
  for (index in seq_along(pattern$children)) if (!match_pattern(pattern$children[[index]], value[[index]], bindings)) return(FALSE)
  TRUE
}
new_evaluator <- function() new_record(calls = 0L)
evaluate <- function(evaluator, expression, environment) {
  kind <- expression$kind
  children <- expression$children
  if (kind %in% c("integer", "boolean", "string")) return(expression$value)
  if (kind == "name") return(get(expression$value, environment, inherits = FALSE))
  if (kind == "fun") return(new_closure(expression$value$spelling, children[[1L]], copy_value_environment(environment)))
  if (kind == "apply") {
    function_value <- evaluate(evaluator, children[[1L]], environment)
    argument <- evaluate(evaluator, children[[2L]], environment)
    evaluator$calls <- evaluator$calls + 1L
    if (inherits(function_value, "ml_builtin")) return(function_value$behavior(argument, expression$position))
    inner <- copy_value_environment(function_value$environment)
    if (function_value$parameter != "_") assign(function_value$parameter, argument, inner)
    return(evaluate(evaluator, function_value$body, inner))
  }
  if (kind == "binary") {
    first <- evaluate(evaluator, children[[1L]], environment)
    operator <- expression$value$spelling
    if (operator == "&&") return(if (first) evaluate(evaluator, children[[2L]], environment) else FALSE)
    if (operator == "||") return(if (first) TRUE else evaluate(evaluator, children[[2L]], environment))
    second <- evaluate(evaluator, children[[2L]], environment)
    return(binary_operation(operator, first, second, expression$value$position))
  }
  if (kind == "negate") return(checked_integer(-evaluate(evaluator, children[[1L]], environment), expression$value$position))
  if (kind == "if") {
    selected <- if (evaluate(evaluator, children[[1L]], environment)) children[[2L]] else children[[3L]]
    return(evaluate(evaluator, selected, environment))
  }
  if (kind == "pair") {
    first <- evaluate(evaluator, children[[1L]], environment)
    second <- evaluate(evaluator, children[[2L]], environment)
    return(structure(list(first, second), class = "ml_pair"))
  }
  if (kind == "list") return(lapply(children, function(child) evaluate(evaluator, child, environment)))
  if (kind == "match") {
    value <- evaluate(evaluator, children[[1L]], environment)
    for (arm in expression$value) {
      bindings <- new.env(hash = TRUE, parent = emptyenv())
      if (match_pattern(arm[[1L]], value, bindings)) {
        inner <- copy_value_environment(environment)
        for (name in ls(bindings, all.names = TRUE)) assign(name, get(name, bindings, inherits = FALSE), inner)
        return(evaluate(evaluator, arm[[2L]], inner))
      }
    }
    runtime_failure(expression$position, "match failure")
  }
  inner <- evaluate_group(evaluator, expression$value, environment)
  evaluate(evaluator, children[[1L]], inner)
}
evaluate_group <- function(evaluator, group, environment) {
  result <- copy_value_environment(environment)
  if (!is.null(group$rec_position)) {
    for (binding in group$bindings) {
      expression <- binding$expression
      assign(binding$name, new_closure(expression$value$spelling, expression$children[[1L]], result), result)
    }
  } else {
    values <- lapply(group$bindings, function(binding) evaluate(evaluator, binding$expression, environment))
    for (index in seq_along(group$bindings)) assign(group$bindings[[index]]$name, values[[index]], result)
  }
  result
}

inference_error <- function(kind, position, ...) {
  stop(structure(list(message = "type inference error", kind = kind, position = position,
                      details = list(...)), class = c("inference_error", "error", "condition")))
}
new_inferencer <- function() new_record(local_bindings = list())
check_type <- function(expected, found, position) {
  found <- force(found)
  expected <- force(expected)
  tryCatch(unify(expected, found), unification_failure = function(failure) inference_error("check", position, expected = expected, found = found, failure = failure))
}
operator_types <- function(operator) {
  if (operator %in% c("+", "-", "*", "/", "mod")) return(list(INT, INT, INT))
  if (operator == "^") return(list(STRING, STRING, STRING))
  if (operator %in% c("&&", "||")) return(list(BOOL, BOOL, BOOL))
  variable <- new_type_variable()
  if (operator == "::") {
    sequence <- ml_type("list", variable)
    return(list(variable, sequence, sequence))
  }
  list(variable, variable, BOOL)
}
infer_expression <- function(inferencer, expression, environment) {
  kind <- expression$kind
  children <- expression$children
  if (kind %in% c("integer", "boolean", "string")) {
    result <- switch(kind, integer = INT, boolean = BOOL, string = STRING)
  } else if (kind == "name") {
    scheme <- environment[[expression$value]]
    if (is.null(scheme)) inference_error("unbound", expression$position, name = expression$value, candidates = names(environment))
    result <- instantiate(scheme)
  } else if (kind == "fun") {
    argument <- new_type_variable()
    inner <- environment
    if (expression$value$spelling != "_") inner[[expression$value$spelling]] <- new_scheme(argument)
    body <- infer_expression(inferencer, children[[1L]], inner)
    result <- ml_type("function", argument, body)
  } else if (kind == "apply") {
    function_type <- resolve_type(infer_expression(inferencer, children[[1L]], environment))
    if (function_type$kind == "variable") {
      argument <- new_type_variable()
      result <- new_type_variable()
      function_type$binding <- ml_type("function", argument, result)
    } else if (function_type$kind == "function") {
      argument <- function_type$children[[1L]]
      result <- function_type$children[[2L]]
    } else {
      inference_error("not_function", children[[1L]]$position, found = function_type)
    }
    found <- infer_expression(inferencer, children[[2L]], environment)
    check_type(argument, found, children[[2L]]$position)
  } else if (kind == "binary") {
    types <- operator_types(expression$value$spelling)
    check_type(types[[1L]], infer_expression(inferencer, children[[1L]], environment), children[[1L]]$position)
    check_type(types[[2L]], infer_expression(inferencer, children[[2L]], environment), children[[2L]]$position)
    result <- types[[3L]]
  } else if (kind == "negate") {
    check_type(INT, infer_expression(inferencer, children[[1L]], environment), children[[1L]]$position)
    result <- INT
  } else if (kind == "if") {
    check_type(BOOL, infer_expression(inferencer, children[[1L]], environment), children[[1L]]$position)
    result <- infer_expression(inferencer, children[[2L]], environment)
    found <- infer_expression(inferencer, children[[3L]], environment)
    check_type(result, found, children[[3L]]$position)
  } else if (kind == "pair") {
    first <- infer_expression(inferencer, children[[1L]], environment)
    second <- infer_expression(inferencer, children[[2L]], environment)
    result <- ml_type("pair", first, second)
  } else if (kind == "list") {
    element <- new_type_variable()
    for (child in children) check_type(element, infer_expression(inferencer, child, environment), child$position)
    result <- ml_type("list", element)
  } else if (kind == "match") {
    matched <- infer_expression(inferencer, children[[1L]], environment)
    result <- new_type_variable()
    for (arm in expression$value) {
      bindings <- new.env(hash = TRUE, parent = emptyenv())
      pattern_type <- infer_pattern(arm[[1L]], bindings)
      check_type(matched, pattern_type, arm[[1L]]$position)
      inner <- environment
      for (name in ls(bindings, all.names = TRUE)) inner[[name]] <- new_scheme(get(name, bindings, inherits = FALSE))
      check_type(result, infer_expression(inferencer, arm[[2L]], inner), arm[[2L]]$position)
    }
  } else {
    inner <- infer_group(inferencer, expression$value, environment, TRUE)
    result <- infer_expression(inferencer, children[[1L]], inner)
  }
  expression$inferred <- result
  result
}
infer_pattern <- function(pattern, bindings) {
  kind <- pattern$kind
  children <- pattern$children
  if (kind == "wildcard") return(new_type_variable())
  if (kind == "name") {
    if (exists(pattern$value, bindings, inherits = FALSE)) inference_error("duplicate_pattern", pattern$position, name = pattern$value)
    result <- new_type_variable()
    assign(pattern$value, result, bindings)
    return(result)
  }
  if (kind %in% c("integer", "boolean", "string")) return(switch(kind, integer = INT, boolean = BOOL, string = STRING))
  if (kind == "pair") {
    first <- infer_pattern(children[[1L]], bindings)
    second <- infer_pattern(children[[2L]], bindings)
    return(ml_type("pair", first, second))
  }
  element <- new_type_variable()
  sequence <- ml_type("list", element)
  if (kind == "cons") {
    check_type(element, infer_pattern(children[[1L]], bindings), children[[1L]]$position)
    check_type(sequence, infer_pattern(children[[2L]], bindings), children[[2L]]$position)
  } else {
    for (child in children) check_type(element, infer_pattern(child, bindings), child$position)
  }
  sequence
}
infer_group <- function(inferencer, group, environment, local_group = FALSE) {
  names <- character()
  for (binding in group$bindings) {
    if (binding$name %in% names) inference_error("duplicate_let", binding$position, name = binding$name)
    names <- c(names, binding$name)
    if (!is.null(group$rec_position) && binding$expression$kind != "fun") inference_error("recursive_function", binding$position, name = binding$name)
  }
  if (is.null(group$rec_position)) {
    inferred <- lapply(group$bindings, function(binding) infer_expression(inferencer, binding$expression, environment))
  } else {
    inferred <- lapply(group$bindings, function(binding) new_type_variable())
    recursive <- environment
    for (index in seq_along(group$bindings)) recursive[[group$bindings[[index]]$name]] <- new_scheme(inferred[[index]])
    for (index in seq_along(group$bindings)) {
      binding <- group$bindings[[index]]
      found <- infer_expression(inferencer, binding$expression, recursive)
      check_type(inferred[[index]], found, binding$position)
    }
  }
  result <- environment
  for (index in seq_along(group$bindings)) {
    binding <- group$bindings[[index]]
    binding$scheme <- generalize(inferred[[index]], environment)
    result[[binding$name]] <- binding$scheme
  }
  if (local_group) inferencer$local_bindings <- c(inferencer$local_bindings, group$bindings)
  result
}

KEYWORDS <- strsplit("let rec and in fun if then else match with true false mod val", " ")[[1L]]
SYMBOLS <- strsplit(";; -> :: : || && <= >= <> ; = < > + - * / ^ ( ) [ ] , |", " ")[[1L]]
ESCAPES <- setNames(c("\n", "\t", "\\", '"'), c("n", "t", "\\", '"'))
new_record <- function(...) list2env(list(...), parent = emptyenv())
new_position <- function(filename, line, column) list(filename = filename, line = line, column = column)
new_token <- function(kind, spelling, value, position) list(kind = kind, spelling = spelling, value = value, position = position)
is_name <- function(token) token$kind == "identifier" && token$spelling != "_"
letter <- function(character) grepl("^[A-Za-z]$", character)
word_character <- function(character) grepl("^[A-Za-z0-9_]$", character)
ml_character <- function(source, index) if (index < 1L || index > nchar(source)) "" else substr(source, index, index)
tokenize <- function(source, filename) {
  tokens <- list()
  index <- line <- column <- 1L
  while (index <= nchar(source)) {
    start <- index
    position <- new_position(filename, line, column)
    character <- ml_character(source, index)
    kind <- value <- NULL
    pair <- substr(source, index, index + 1L)
    if (character %in% c(" ", "\n")) {
      index <- index + 1L
    } else if (pair == "(*") {
      closing <- regexpr("*)", substr(source, index + 2L, nchar(source)), fixed = TRUE)[[1L]]
      if (closing < 0L) {
        kind <- "invalid"
        value <- "unterminated comment"
        index <- nchar(source) + 1L
      } else {
        index <- index + closing + 3L
      }
    } else if (grepl("^[0-9]$", character)) {
      index <- index + 1L
      while (grepl("^[0-9]$", ml_character(source, index))) index <- index + 1L
      digits <- sub("^0+", "", substr(source, start, index - 1L))
      if (!nzchar(digits)) digits <- "0"
      if (nchar(digits) > 10L || (nchar(digits) == 10L && as.numeric(digits) > 2147483647)) {
        kind <- "invalid"
        value <- "integer literal too large"
      } else {
        kind <- "integer"
        value <- as.numeric(digits)
      }
    } else if (letter(character) || character == "_") {
      index <- index + 1L
      while (word_character(ml_character(source, index)) || ml_character(source, index) == "'") index <- index + 1L
      value <- substr(source, start, index - 1L)
      kind <- if (value %in% KEYWORDS) value else "identifier"
    } else if (character == "'" && grepl("^[a-z]$", ml_character(source, index + 1L))) {
      index <- index + 2L
      while (word_character(ml_character(source, index))) index <- index + 1L
      kind <- "type_variable"
      value <- substr(source, start, index - 1L)
    } else if (character == '"') {
      index <- index + 1L
      decoded <- character()
      invalid_escape <- FALSE
      while (index <= nchar(source) && !ml_character(source, index) %in% c('"', "\n")) {
        if (ml_character(source, index) == "\\" && index < nchar(source) && ml_character(source, index + 1L) != "\n") {
          escape <- ml_character(source, index + 1L)
          if (escape %in% names(ESCAPES)) decoded <- c(decoded, ESCAPES[[escape]]) else invalid_escape <- TRUE
          index <- index + 2L
        } else {
          decoded <- c(decoded, ml_character(source, index))
          index <- index + 1L
        }
      }
      if (index > nchar(source) || ml_character(source, index) == "\n") {
        kind <- "invalid"
        value <- "unterminated string"
      } else {
        index <- index + 1L
        kind <- if (invalid_escape) "invalid" else "string"
        value <- if (invalid_escape) "invalid escape sequence" else paste(decoded, collapse = "")
      }
    } else if (pair %in% SYMBOLS) {
      index <- index + 2L
      kind <- value <- pair
    } else if (character %in% SYMBOLS) {
      index <- index + 1L
      kind <- value <- character
    } else {
      index <- index + 1L
      kind <- "invalid"
      value <- paste0("illegal character '", character, "'")
    }
    consumed <- substr(source, start, index - 1L)
    if (!is.null(kind)) tokens[[length(tokens) + 1L]] <- new_token(kind, consumed, value, position)
    characters <- strsplit(consumed, "", fixed = TRUE)[[1L]]
    newlines <- which(characters == "\n")
    if (length(newlines)) {
      line <- line + length(newlines)
      column <- length(characters) - tail(newlines, 1L) + 1L
    } else {
      column <- column + nchar(consumed)
    }
  }
  eof_line <- sum(strsplit(source, "", fixed = TRUE)[[1L]] == "\n") + 1L
  tokens[[length(tokens) + 1L]] <- new_token("EOF", "", NULL, new_position(filename, eof_line, 1L))
  tokens
}

